const produkty = [{ nazwa: "Laptop", cena: 1000 }, { nazwa: "Mysz", cena: 50 }];

const przecenione = produkty.map(p => ({
  ...p,
  cena: p.cena * 0.9,
  przecena: true
}));

console.log(przecenione);
// [{ nazwa: 'Laptop', cena: 900, przecena: true }, { nazwa: 'Mysz', cena: 45, przecena: true }]
